CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS roles (id SERIAL PRIMARY KEY, name VARCHAR(32) UNIQUE NOT NULL, permissions JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, role_id INT NOT NULL REFERENCES roles, name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS room_types (id SERIAL PRIMARY KEY, name VARCHAR(50) UNIQUE NOT NULL, base_price NUMERIC(10,2) NOT NULL CHECK(base_price>=0), capacity INT NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS rooms (id SERIAL PRIMARY KEY, room_type_id INT NOT NULL REFERENCES room_types, room_number VARCHAR(10) UNIQUE NOT NULL, floor VARCHAR(10), status VARCHAR(20) NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Occupied','Reserved','Cleaning','Maintenance','Out of Service')));
CREATE TABLE IF NOT EXISTS guests (id SERIAL PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(255), phone VARCHAR(30), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS guests_email_unique ON guests(email) WHERE email IS NOT NULL;
CREATE TABLE IF NOT EXISTS reservations (id SERIAL PRIMARY KEY, guest_id INT NOT NULL REFERENCES guests, room_id INT NOT NULL REFERENCES rooms, check_in DATE NOT NULL, check_out DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Confirmed' CHECK(status IN ('Confirmed','Checked In','Checked Out','Cancelled')), nightly_rate NUMERIC(10,2) NOT NULL CHECK(nightly_rate>=0), created_by INT REFERENCES users, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(check_out>check_in));
ALTER TABLE reservations ADD CONSTRAINT reservations_no_overlap EXCLUDE USING gist (room_id WITH =, daterange(check_in,check_out,'[)') WITH &&) WHERE (status IN ('Confirmed','Checked In'));
CREATE TABLE IF NOT EXISTS invoices (id SERIAL PRIMARY KEY, reservation_id INT NOT NULL UNIQUE REFERENCES reservations, amount NUMERIC(10,2) NOT NULL CHECK(amount>=0), status VARCHAR(20) NOT NULL DEFAULT 'Unpaid' CHECK(status IN ('Unpaid','Paid')), issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY, invoice_id INT NOT NULL REFERENCES invoices, amount NUMERIC(10,2) NOT NULL CHECK(amount>=0), method VARCHAR(30) NOT NULL, reference VARCHAR(100), is_mock BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS housekeeping_tasks (id SERIAL PRIMARY KEY, room_id INT NOT NULL REFERENCES rooms, assigned_to INT REFERENCES users, status VARCHAR(20) NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','In Progress','Done')), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, user_id INT REFERENCES users ON DELETE SET NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(50), entity_id INT, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (key VARCHAR(80) PRIMARY KEY, value JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id SERIAL PRIMARY KEY, user_id INT REFERENCES users ON DELETE CASCADE, message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reservations_dates_idx ON reservations(check_in,check_out); CREATE INDEX IF NOT EXISTS tasks_status_idx ON housekeeping_tasks(status); CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at DESC);
